CREATE TABLE IF NOT EXISTS payment_transaction (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  payment_no VARCHAR(64) NOT NULL,
  biz_type VARCHAR(30) NOT NULL,
  biz_order_id BIGINT DEFAULT NULL,
  biz_order_no VARCHAR(64) NOT NULL,
  user_id BIGINT DEFAULT NULL,
  store_id BIGINT DEFAULT NULL,
  pay_channel VARCHAR(30) NOT NULL,
  channel_trade_no VARCHAR(64) DEFAULT NULL,
  out_trade_no VARCHAR(64) DEFAULT NULL,
  pay_status VARCHAR(20) NOT NULL DEFAULT 'pending',
  pay_amount DECIMAL(18,2) NOT NULL DEFAULT 0.00,
  currency_code VARCHAR(10) NOT NULL DEFAULT 'CNY',
  callback_count INT NOT NULL DEFAULT 0,
  request_time TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  pay_time TIMESTAMP DEFAULT NULL,
  callback_time TIMESTAMP DEFAULT NULL,
  expire_time TIMESTAMP DEFAULT NULL,
  remark VARCHAR(255) DEFAULT NULL,
  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (id),
  CONSTRAINT uk_payment_no UNIQUE (payment_no),
  CONSTRAINT uk_out_trade_no UNIQUE (out_trade_no)
);

CREATE INDEX IF NOT EXISTS payment_transaction__idx_biz_order_no ON payment_transaction (biz_order_no);

CREATE INDEX IF NOT EXISTS payment_transaction__idx_biz_type_status ON payment_transaction (biz_type, pay_status);

