INSERT INTO mini_admin_staff_store (staff_id, store_id, is_primary, created_at)
SELECT 1, s.id, 1, CURRENT_TIMESTAMP
FROM store s
WHERE s.id = (SELECT MIN(id) FROM store)
  AND NOT EXISTS (
    SELECT 1
    FROM mini_admin_staff_store ss
    WHERE ss.staff_id = 1
      AND ss.store_id = s.id
  );

UPDATE mini_admin_staff_store AS ss SET is_primary = 1 FROM store AS s WHERE s.id = ss.store_id AND ss.staff_id = 1 AND s.id = (SELECT MIN(id) FROM store);

